(function() {
    'use strict';

    class GreenBondAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'GreenBond: Sustainable Finance & Impact-Linked Instruments';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    name_key: 'round_1_name',
                    name_default: 'Framework Development',
                    briefing: 'Welcome to the Verdana Capital Markets Sustainable Finance Desk. You are managing three simultaneous debt issuances:<br><br><b>Helios Renewables S.A.</b> (EUR 500M Green Bond) — offshore wind developer seeking EU Taxonomy-aligned green financing for Baltic Sea project Ventara Offshore I.<br><b>Avanta Housing Trust</b> (GBP 300M Social Bond) — UK affordable housing provider financing 1,200 new homes and energy retrofits.<br><b>NordChem AG</b> (EUR 600M SLB) — German chemicals manufacturer linking cost of capital to 2030 decarbonization targets.<br><br>Define the framework for each instrument: eligible project scope, taxonomy alignment, target populations, KPI selection, and SPT ambition.',
                    regulatory: false
                },
                {
                    name_key: 'round_2_name',
                    name_default: 'Pricing and Structuring',
                    briefing: 'Frameworks are drafted. Now price each instrument and select structural parameters.<br><br><b>Green Bond:</b> Comparable conventional Helios parent bonds trade at MS+95bp. European offshore wind green bonds have achieved 2-6bp greenium. Select your greenium estimate, tenor, and SPO provider.<br><b>Social Bond:</b> UK housing association social bonds have historically attracted 3-7bp social premium. Choose impact metrics approach and SPO scope.<br><b>SLB:</b> Model coupon step-up scenarios and select baseline verification level. Consider whether to pursue EU Taxonomy transition alignment.',
                    regulatory: false
                },
                {
                    name_key: 'round_3_name',
                    name_default: 'SPO and Regulatory Response',
                    briefing: 'A major regulatory event has disrupted your transactions. Respond to the EU Taxonomy TSC amendment and the updated SBTi sector benchmark while managing SPO provider communications.',
                    regulatory: true,
                    regAlert: 'The European Commission has published a draft amendment tightening offshore wind TSC from 100 to 22 gCO2e/kWh and requiring no-net-loss biodiversity assessment for Marine Protected Area installations. ESMA has advised precautionary methodology for in-progress reviews. Simultaneously, the SBTi has increased the chemicals sector 1.5C reduction requirement from 42% to 50% by 2030.'
                },
                {
                    name_key: 'round_4_name',
                    name_default: 'Investor Roadshow',
                    briefing: 'Present all three instruments to institutional investors. A Eurozone insurer (SFDR Article 9 mandate) will challenge Taxonomy alignment. A UK pension fund will probe social outcomes methodology. A Nordic sovereign wealth fund will question Scope 3 exclusion from NordChem KPIs.<br><br>Make final documentation decisions that balance transparency with commercial positioning. Higher disclosure quality reduces greenwashing risk but may expose analytical gaps to investor scrutiny.',
                    regulatory: false
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    impactCredibility: 0,
                    greenwashingRisk: 0,
                    commercialPerformance: 0,
                    regulatoryResilience: 0,
                    compositeScore: 0,
                    impactHistory: [],
                    gwRiskHistory: [],
                    commercialHistory: [],
                    regulatoryHistory: [],
                    compositeHistory: [],
                    cumulativeImpact: 0,
                    cumulativeGwRisk: 0,
                    cumulativeCommercial: 0,
                    cumulativeRegulatory: 0,
                    r1Decisions: {},
                    r2Decisions: {}
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    green_scope: 'moderate',
                    taxonomy: 'icma_gbp',
                    dnsh: 'ecologist',
                    target_pop: 'moderate',
                    social_cat: 'housing_retrofit',
                    afford: 'lha',
                    kpi1: 'scope12',
                    kpi2: 'voc',
                    spt: 'science',
                    stepup: '25'
                };
            }
            this._updateBriefing(state);
            this._registerLifecycle();
        }

        _writeScore(ds, score) {
            var s = Math.max(0, Math.min(100, Math.round(score || 0)));
            if (!ds.performance || typeof ds.performance !== 'object') { ds.performance = {}; }
            ds.performance.overallScore = s;
            ds.score = s;
            return s;
        }

        _registerLifecycle() {
            var self = this;
            try {
                var sim = window.mySimulation;
                if (sim && sim.periodManager && typeof sim.periodManager.addHook === 'function') {
                    sim.periodManager.addHook('afterAdvance', function(st) { try { self._updateBriefing(st); } catch (e) {} });
                }
                if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                    sim.eventBus.on('period:undone', function(st) { try { self._updateBriefing(st); } catch (e) {} });
                }
            } catch (e) {}
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.briefing;

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) nameEl.textContent = round.name_default;

            var regAlert = document.getElementById('regulatoryAlert');
            var regText = document.getElementById('regulatoryAlertText');
            if (regAlert) {
                regAlert.style.display = round.regulatory ? 'block' : 'none';
                if (regText && round.regAlert) regText.innerHTML = round.regAlert;
            }

            var period = state.currentPeriod || 1;
            for (var r = 1; r <= 4; r++) {
                var show = (r === period);
                var gEl = document.getElementById('greenR' + r);
                if (gEl) gEl.style.display = show ? 'block' : 'none';
                var sEl = document.getElementById('socialR' + r);
                if (sEl) sEl.style.display = show ? 'block' : 'none';
                var lEl = document.getElementById('slbR' + r);
                if (lEl) lEl.style.display = show ? 'block' : 'none';
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var gs = document.getElementById('greenScopeInput');
                if (gs) decisions.green_scope = gs.value;
                var tx = document.getElementById('taxonomyInput');
                if (tx) decisions.taxonomy = tx.value;
                var dn = document.getElementById('dnshInput');
                if (dn) decisions.dnsh = dn.value;
                var tp = document.getElementById('targetPopInput');
                if (tp) decisions.target_pop = tp.value;
                var sc = document.getElementById('socialCatInput');
                if (sc) decisions.social_cat = sc.value;
                var af = document.getElementById('affordInput');
                if (af) decisions.afford = af.value;
                var k1 = document.getElementById('kpi1Input');
                if (k1) decisions.kpi1 = k1.value;
                var k2 = document.getElementById('kpi2Input');
                if (k2) decisions.kpi2 = k2.value;
                var sp = document.getElementById('sptInput');
                if (sp) decisions.spt = sp.value;
                var su = document.getElementById('stepupInput');
                if (su) decisions.stepup = su.value;

                if (decisions.kpi1 === decisions.kpi2) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('kpi_dup_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var gi = document.getElementById('greeniumInput');
                if (gi) decisions.greenium = parseFloat(gi.value);
                var te = document.getElementById('tenorInput');
                if (te) decisions.tenor = te.value;
                var po = document.getElementById('spoProviderInput');
                if (po) decisions.spo_provider = po.value;
                var pm = document.getElementById('socialPremiumInput');
                if (pm) decisions.social_premium = parseFloat(pm.value);
                var st = document.getElementById('socialTenorInput');
                if (st) decisions.social_tenor = st.value;
                var im = document.getElementById('impactMetricsInput');
                if (im) decisions.impact_metrics = im.value;
                var ss = document.getElementById('spoScopeInput');
                if (ss) decisions.spo_scope = ss.value;
                var bv = document.getElementById('baselineVerInput');
                if (bv) decisions.baseline_ver = bv.value;
                var tt = document.getElementById('taxTransInput');
                if (tt) decisions.tax_trans = tt.value;

                if (decisions.greenium < 0 || decisions.greenium > 15) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('greenium_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 3) {
                var fr = document.getElementById('frameworkResponseInput');
                if (fr) decisions.framework_response = fr.value;
                var sq = document.getElementById('spoQualInput');
                if (sq) decisions.spo_qual = sq.value;
                var sa = document.getElementById('socialAdjustInput');
                if (sa) decisions.social_adjust = sa.value;
                var sr = document.getElementById('sptRecalInput');
                if (sr) decisions.spt_recal = sr.value;
            } else if (period === 4) {
                var tb = document.getElementById('taxonomyTableInput');
                if (tb) decisions.taxonomy_table = tb.value;
                var or2 = document.getElementById('outcomesReportInput');
                if (or2) decisions.outcomes_report = or2.value;
                var bd = document.getElementById('benchmarkDiscInput');
                if (bd) decisions.benchmark_disc = bd.value;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var impact = 0;
            var gwRisk = 0;
            var commercial = 0;
            var regulatory = 0;

            if (period === 1) {
                ds.r1Decisions = {
                    green_scope: d.green_scope,
                    taxonomy: d.taxonomy,
                    dnsh: d.dnsh,
                    target_pop: d.target_pop,
                    social_cat: d.social_cat,
                    afford: d.afford,
                    kpi1: d.kpi1,
                    kpi2: d.kpi2,
                    spt: d.spt,
                    stepup: d.stepup
                };

                var scopeMap = { narrow: 9, moderate: 6, broad: 3 };
                var taxMap = { eu_gbs: 9, icma_gbp: 5 };
                var dnshMap = { desktop: 2, ecologist: 6, full_eia: 9 };
                impact += (scopeMap[d.green_scope] || 6) * 0.15;
                impact += (taxMap[d.taxonomy] || 5) * 0.1;
                impact += (dnshMap[d.dnsh] || 6) * 0.1;

                gwRisk += d.green_scope === 'broad' ? 8 : d.green_scope === 'moderate' ? 4 : 1;
                gwRisk += d.taxonomy === 'icma_gbp' ? 5 : 1;
                gwRisk += d.dnsh === 'desktop' ? 8 : d.dnsh === 'ecologist' ? 4 : 1;

                var tpMap = { narrow: 9, moderate: 6, broad: 3 };
                var catMap = { housing: 7, housing_retrofit: 6, all: 4 };
                var afMap = { median_income: 8, lha: 6, national_rent: 4 };
                impact += (tpMap[d.target_pop] || 6) * 0.1;
                impact += (catMap[d.social_cat] || 6) * 0.08;
                impact += (afMap[d.afford] || 6) * 0.07;

                gwRisk += d.target_pop === 'broad' ? 6 : d.target_pop === 'moderate' ? 3 : 1;
                gwRisk += d.social_cat === 'all' ? 4 : d.social_cat === 'housing_retrofit' ? 2 : 1;

                var kpiMateriality = 0;
                if (d.kpi1 === 'scope12') kpiMateriality += 9;
                else if (d.kpi1 === 'intensity') kpiMateriality += 7;
                else if (d.kpi1 === 'voc') kpiMateriality += 6;
                else if (d.kpi1 === 'renewable') kpiMateriality += 5;
                else kpiMateriality += 3;

                if (d.kpi2 !== 'none') {
                    if (d.kpi2 === 'voc') kpiMateriality += 5;
                    else if (d.kpi2 === 'scope12') kpiMateriality += 4;
                    else kpiMateriality += 2;
                    kpiMateriality = kpiMateriality / 1.5;
                }

                var sptMap = { conservative: 2, science: 7, aspirational: 9 };
                impact += (kpiMateriality) * 0.12;
                impact += (sptMap[d.spt] || 7) * 0.12;

                gwRisk += d.spt === 'conservative' ? 8 : d.spt === 'science' ? 3 : 1;
                gwRisk += d.kpi1 !== 'scope12' && d.kpi1 !== 'intensity' ? 4 : 1;

                var stepCommercial = d.stepup === '15' ? 7 : d.stepup === '25' ? 5 : 3;
                commercial = (d.green_scope === 'broad' ? 8 : d.green_scope === 'moderate' ? 5 : 3) * 0.3;
                commercial += (d.taxonomy === 'icma_gbp' ? 7 : 4) * 0.3;
                commercial += (d.target_pop === 'broad' ? 7 : d.target_pop === 'moderate' ? 5 : 3) * 0.2;
                commercial += stepCommercial * 0.2;

                regulatory = (d.taxonomy === 'eu_gbs' ? 9 : 4) * 0.5;
                regulatory += (d.dnsh === 'full_eia' ? 9 : d.dnsh === 'ecologist' ? 5 : 2) * 0.3;
                regulatory += (d.spt === 'aspirational' ? 8 : d.spt === 'science' ? 6 : 2) * 0.2;

            } else if (period === 2) {
                ds.r2Decisions = {
                    greenium: d.greenium,
                    tenor: d.tenor,
                    spo_provider: d.spo_provider,
                    social_premium: d.social_premium,
                    social_tenor: d.social_tenor,
                    impact_metrics: d.impact_metrics,
                    spo_scope: d.spo_scope,
                    baseline_ver: d.baseline_ver,
                    tax_trans: d.tax_trans
                };

                var optimalGreenium = ds.r1Decisions.taxonomy === 'eu_gbs' ? 5 : 3;
                if (ds.r1Decisions.dnsh === 'full_eia') optimalGreenium += 1;
                var greeniumDiff = Math.abs((d.greenium || 4) - optimalGreenium);
                var greeniumScore = Math.max(0, 9 - greeniumDiff * 1.5);

                var spoMap = { vigeo: 9, greencert: 5, ecoverify: 2 };
                var metricsMap = { outcome: 9, mixed: 6, output: 3 };
                var scopeMap2 = { full: 8, limited: 4 };
                var verMap = { reasonable: 9, limited: 6, internal: 2 };

                impact = greeniumScore * 0.15;
                impact += (spoMap[d.spo_provider] || 5) * 0.15;
                impact += (metricsMap[d.impact_metrics] || 6) * 0.2;
                impact += (scopeMap2[d.spo_scope] || 4) * 0.15;
                impact += (verMap[d.baseline_ver] || 6) * 0.15;
                impact += (d.tax_trans === 'yes' ? 8 : 4) * 0.1;

                gwRisk = 0;
                gwRisk += d.spo_provider === 'ecoverify' ? 8 : d.spo_provider === 'greencert' ? 4 : 1;
                gwRisk += d.impact_metrics === 'output' ? 6 : d.impact_metrics === 'mixed' ? 3 : 1;
                gwRisk += d.spo_scope === 'limited' ? 5 : 1;
                gwRisk += d.baseline_ver === 'internal' ? 7 : d.baseline_ver === 'limited' ? 3 : 1;

                var spoCommercial = d.spo_provider === 'ecoverify' ? 8 : d.spo_provider === 'greencert' ? 6 : 4;
                commercial = greeniumScore * 0.3;
                commercial += spoCommercial * 0.2;
                commercial += (d.impact_metrics === 'output' ? 7 : d.impact_metrics === 'mixed' ? 5 : 3) * 0.15;
                commercial += (d.baseline_ver === 'internal' ? 8 : d.baseline_ver === 'limited' ? 5 : 3) * 0.15;
                commercial += (d.tax_trans === 'yes' ? 7 : 5) * 0.1;

                regulatory = (spoMap[d.spo_provider] || 5) * 0.3;
                regulatory += (verMap[d.baseline_ver] || 6) * 0.3;
                regulatory += (d.tax_trans === 'yes' ? 8 : 4) * 0.2;
                regulatory += (d.spo_scope === 'full' ? 7 : 3) * 0.2;

            } else if (period === 3) {
                var frMap = { amend: 9, maintain: 4, delay: 6 };
                var sqMap = { commission: 9, accept: 4, negotiate: 5 };
                var saMap = { tighten: 8, maintain: 4 };
                var srMap = { revise_up: 9, maintain: 4 };

                impact = (frMap[d.framework_response] || 4) * 0.25;
                impact += (sqMap[d.spo_qual] || 4) * 0.25;
                impact += (saMap[d.social_adjust] || 4) * 0.25;
                impact += (srMap[d.spt_recal] || 4) * 0.25;

                gwRisk = 0;
                gwRisk += d.framework_response === 'maintain' ? 7 : d.framework_response === 'delay' ? 3 : 1;
                gwRisk += d.spo_qual === 'accept' ? 6 : d.spo_qual === 'negotiate' ? 5 : 1;
                gwRisk += d.social_adjust === 'maintain' ? 4 : 1;
                gwRisk += d.spt_recal === 'maintain' ? 6 : 1;

                commercial = (d.framework_response === 'amend' ? 3 : d.framework_response === 'maintain' ? 8 : 2) * 0.35;
                commercial += (d.spo_qual === 'accept' ? 7 : d.spo_qual === 'negotiate' ? 5 : 3) * 0.25;
                commercial += (d.social_adjust === 'maintain' ? 7 : 4) * 0.2;
                commercial += (d.spt_recal === 'maintain' ? 7 : 4) * 0.2;

                regulatory = (frMap[d.framework_response] || 4) * 0.35;
                regulatory += (sqMap[d.spo_qual] || 4) * 0.25;
                regulatory += (saMap[d.social_adjust] || 4) * 0.2;
                regulatory += (srMap[d.spt_recal] || 4) * 0.2;

            } else if (period === 4) {
                var ttMap = { include: 9, exclude: 3 };
                var orMap = { full_outcomes: 9, output_only: 3 };
                var bdMap = { full: 9, spt_only: 3 };

                impact = (ttMap[d.taxonomy_table] || 3) * 0.33;
                impact += (orMap[d.outcomes_report] || 3) * 0.34;
                impact += (bdMap[d.benchmark_disc] || 3) * 0.33;

                gwRisk = 0;
                gwRisk += d.taxonomy_table === 'exclude' ? 5 : 1;
                gwRisk += d.outcomes_report === 'output_only' ? 5 : 1;
                gwRisk += d.benchmark_disc === 'spt_only' ? 5 : 1;

                commercial = (d.taxonomy_table === 'exclude' ? 7 : 4) * 0.33;
                commercial += (d.outcomes_report === 'output_only' ? 7 : 4) * 0.34;
                commercial += (d.benchmark_disc === 'spt_only' ? 7 : 4) * 0.33;

                regulatory = (ttMap[d.taxonomy_table] || 3) * 0.4;
                regulatory += (orMap[d.outcomes_report] || 3) * 0.3;
                regulatory += (bdMap[d.benchmark_disc] || 3) * 0.3;
            }

            impact = Math.round(Math.min(10, Math.max(0, impact)) * 10) / 10;
            gwRisk = Math.round(Math.min(10, Math.max(0, gwRisk / 3)) * 10) / 10;
            commercial = Math.round(Math.min(10, Math.max(0, commercial)) * 10) / 10;
            regulatory = Math.round(Math.min(10, Math.max(0, regulatory)) * 10) / 10;

            var gwScore = Math.round((10 - gwRisk) * 10) / 10;
            var composite = Math.round((impact * 0.35 + gwScore * 0.25 + commercial * 0.25 + regulatory * 0.15) * 10) / 10;

            ds.impactCredibility = impact;
            ds.greenwashingRisk = gwRisk;
            ds.commercialPerformance = commercial;
            ds.regulatoryResilience = regulatory;
            ds.compositeScore = composite;

            ds.cumulativeImpact += impact;
            ds.cumulativeGwRisk += gwRisk;
            ds.cumulativeCommercial += commercial;
            ds.cumulativeRegulatory += regulatory;

            ds.impactHistory.push(impact);
            ds.gwRiskHistory.push(gwRisk);
            ds.commercialHistory.push(commercial);
            ds.regulatoryHistory.push(regulatory);
            ds.compositeHistory.push(composite);

            var _avgComp = ds.compositeHistory.reduce(function(s, v) { return s + v; }, 0) / ds.compositeHistory.length;
            this._writeScore(ds, _avgComp * 10);

            return {
                period: period,
                impact: impact,
                gwRisk: gwRisk,
                gwScore: gwScore,
                commercial: commercial,
                regulatory: regulatory,
                composite: composite,
                overallScore: Math.round(Math.min(100, Math.max(0, composite * 10)))
            };
        }

