        getPerformanceSummary(history) {
            if (!history.length) return {};
            var composites = history.map(function(r) { return r.results ? r.results.composite || 0 : 0; });
            var avgComposite = composites.reduce(function(s, v) { return s + v; }, 0) / composites.length;
            var lastGwRisk = history[history.length - 1].results ? history[history.length - 1].results.gwRisk || 0 : 0;
            var lastImpact = history[history.length - 1].results ? history[history.length - 1].results.impact || 0 : 0;

            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var performance = T('perf_developing');
            if (avgComposite >= 7 && lastGwRisk <= 3) performance = T('perf_distinguished');
            else if (avgComposite >= 5.5 && lastGwRisk <= 5) performance = T('perf_competent');
            else if (avgComposite >= 4) performance = T('perf_emerging');

            var insights = [];
            if (lastGwRisk > 5) {
                insights.push(T('insight_high_gw'));
            }
            if (lastImpact >= 7) {
                insights.push(T('insight_strong_impact'));
            }
            if (avgComposite >= 7) {
                insights.push(T('insight_excellent'));
            }
            if (lastGwRisk <= 2 && avgComposite < 5) {
                insights.push(T('insight_lowgw_weak'));
            }

            return {
                avgComposite: Math.round(avgComposite * 10) / 10,
                finalGwRisk: lastGwRisk,
                finalImpact: lastImpact,
                performance: performance,
                insights: insights
            };
        }

